import { NextResponse } from 'next/server';
import { getSupabaseServer, requireUser } from '../../../lib/supabase/server';
export const runtime='nodejs';
export async function GET(request){try{const u=await requireUser(request),db=getSupabaseServer();const {data,error}=await db.from('vendors').select('*,menus(id,name,status,created_at,menu_items(id,name,price))').eq('owner_id',u.id).order('created_at',{ascending:false});if(error)throw error;return NextResponse.json({vendors:data||[]})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':'Unable to load vendor data.'},{status:e.message==='Unauthorized'?401:500})}}
export async function POST(request){try{const u=await requireUser(request);const b=await request.json();if(!b.name?.trim())return NextResponse.json({error:'Vendor name is required.'},{status:400});const db=getSupabaseServer();const {data,error}=await db.from('vendors').insert({owner_id:u.id,name:b.name.trim(),description:b.description||null,contact_email:b.contact_email||u.email||null,phone:b.phone||null,address:b.address||null,status:'Pending'}).select().single();if(error)throw error;return NextResponse.json({vendor:data},{status:201})}catch(e){return NextResponse.json({error:e.message==='Unauthorized'?'Unauthorized.':'Unable to create vendor.'},{status:e.message==='Unauthorized'?401:500})}}
